"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[2559],{8918(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>c,default:()=>u,frontMatter:()=>d,metadata:()=>a,toc:()=>h});const a=JSON.parse('{"id":"part2-backend-platform-security/sso-oauth2-oidc-primer","title":"SSO, OAuth 2.0, and OpenID Connect: The Identity Primer","description":"Authentication terminology feels confusing because several layers happen during one click on \u201cSign in.\u201d This chapter separates the user experience, delegation protocol, identity protocol, browser session, and API auth...","source":"@site/docs/part2-backend-platform-security/06-sso-oauth2-oidc-primer.mdx","sourceDirName":"part2-backend-platform-security","slug":"/part2-backend-platform-security/06-sso-oauth2-oidc-primer","permalink":"/tutorials/part2-backend-platform-security/06-sso-oauth2-oidc-primer","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":6,"frontMatter":{"title":"SSO, OAuth 2.0, and OpenID Connect: The Identity Primer","slug":"/part2-backend-platform-security/06-sso-oauth2-oidc-primer","description":"Authentication terminology feels confusing because several layers happen during one click on \u201cSign in.\u201d This chapter separates the user experience, delegation protocol, identity protocol, browser session, and API auth...","sidebar_label":"7. SSO, OAuth 2.0, and OIDC primer","pagination_label":"7. SSO, OAuth 2.0, and OIDC primer","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"6. Background tasks and retries","permalink":"/tutorials/part2-backend-platform-security/05-background-tasks-and-retries"},"next":{"title":"8. OIDC, OAuth 2.0, and PKCE in FastAPI","permalink":"/tutorials/part2-backend-platform-security/07-oidc-oauth2-pkce-fastapi"}}');var i=n(4848),o=n(8453),s=n(8172);const r=JSON.parse('{"sourcePath":"part2-backend-platform-security/06-sso-oauth2-oidc-primer.html","route":"/part2-backend-platform-security/06-sso-oauth2-oidc-primer","kind":"chapter","partId":"part2","partLabel":"Part II - Backend, Platform & Security","accent":"teal","heading":"SSO, OAuth 2.0, and OpenID Connect: The Identity Primer","title":"SSO, OAuth 2.0, and OpenID Connect: The Identity Primer","description":"Authentication terminology feels confusing because several layers happen during one click on \u201cSign in.\u201d This chapter separates the user experience, delegation protocol, identity protocol, browser session, and API auth...","readingMinutes":6,"bodyClass":"","normalizeMath":false,"toc":[{"id":"1-start-with-the-problem-applications-should-not-collect-every-password","label":"1) Start with the problem: applications should not collect every password"},{"id":"2-sso-is-an-outcome-not-a-token-format","label":"2) SSO is an outcome, not a token format"},{"id":"3-oauth-2-0-delegates-access-to-an-api","label":"3) OAuth 2.0 delegates access to an API"},{"id":"4-oidc-adds-a-standard-authentication-result","label":"4) OIDC adds a standard authentication result"},{"id":"5-keep-id-tokens-access-tokens-refresh-tokens-and-sessions-separate","label":"5) Keep ID tokens, access tokens, refresh tokens, and sessions separate"},{"id":"6-why-authorization-code-with-pkce-is-the-default-teaching-flow","label":"6) Why Authorization Code with PKCE is the default teaching flow"},{"id":"7-authentication-is-not-application-authorization","label":"7) Authentication is not application authorization"},{"id":"8-common-mistakes-and-the-correct-mental-model","label":"8) Common mistakes and the correct mental model"},{"id":"9-the-flow-you-will-implement-next","label":"9) The flow you will implement next"}],"html":"<p class=\\"lead\\">Authentication terminology feels confusing because several\\n    layers happen during one click on \u201cSign in.\u201d This chapter separates the\\n    user experience, delegation protocol, identity protocol, browser session,\\n    and API authorization before the next chapter implements the complete\\n    flow in React and FastAPI.</p>\\n\\n    <div class=\\"tr-note\\">\\n      <strong>The three-sentence model</strong>\\n      <ul>\\n        <li><strong>SSO is the experience:</strong> authenticate once with a trusted identity provider and use more than one application without entering credentials again.</li>\\n        <li><strong>OAuth 2.0 is delegated authorization:</strong> a client obtains an access token that lets it call a resource server within an approved scope.</li>\\n        <li><strong>OpenID Connect (OIDC) adds authentication:</strong> it standardizes how a client learns which user authenticated, principally through an ID token with identity claims.</li>\\n      </ul>\\n    </div>\\n\\n    <h2 id=\\"1-start-with-the-problem-applications-should-not-collect-every-password\\">1) Start with the problem: applications should not collect every password</h2>\\n\\n    <p>Suppose your company has ten internal applications. Without federation,\\n    every application could create its own username and password database. That\\n    produces ten password stores, ten account-recovery processes, and ten\\n    opportunities to implement authentication badly.</p>\\n\\n    <p>A better design delegates authentication to an\\n    <strong>identity provider (IdP)</strong>, such as Microsoft Entra ID,\\n    Google Identity, Okta, or an internal standards-compliant provider. The\\n    application redirects the user to the IdP. The IdP handles credentials,\\n    passkeys, MFA, risk checks, and account policy, then returns a\\n    cryptographically verifiable result to the application.</p>\\n\\n    <div class=\\"figure-card\\">\\n      <h3 id=\\"visual-one-sign-in-separate-trust-boundaries\\">Visual: one sign-in, separate trust boundaries</h3>\\n      <svg class=\\"viz\\" viewBox=\\"0 0 980 260\\" role=\\"img\\" aria-label=\\"User, application, identity provider, and API trust boundaries\\">\\n        <defs>\\n          <marker id=\\"identity-arrow\\" viewBox=\\"0 0 10 10\\" refX=\\"9\\" refY=\\"5\\" markerWidth=\\"8\\" markerHeight=\\"8\\" orient=\\"auto\\">\\n            <path d=\\"M0 0 L10 5 L0 10 z\\" class=\\"accentFill\\"></path>\\n          </marker>\\n          <marker id=\\"identity-arrow-purple\\" viewBox=\\"0 0 10 10\\" refX=\\"9\\" refY=\\"5\\" markerWidth=\\"8\\" markerHeight=\\"8\\" orient=\\"auto\\">\\n            <path d=\\"M0 0 L10 5 L0 10 z\\" class=\\"accent2Fill\\"></path>\\n          </marker>\\n        </defs>\\n        <rect x=\\"24\\" y=\\"72\\" width=\\"170\\" height=\\"112\\" rx=\\"14\\" class=\\"box2\\"></rect>\\n        <text x=\\"109\\" y=\\"112\\" text-anchor=\\"middle\\" class=\\"title\\">User</text>\\n        <text x=\\"109\\" y=\\"140\\" text-anchor=\\"middle\\" class=\\"muted\\">browser</text>\\n\\n        <rect x=\\"260\\" y=\\"72\\" width=\\"190\\" height=\\"112\\" rx=\\"14\\" class=\\"box\\"></rect>\\n        <text x=\\"355\\" y=\\"112\\" text-anchor=\\"middle\\" class=\\"title\\">Client app</text>\\n        <text x=\\"355\\" y=\\"140\\" text-anchor=\\"middle\\" class=\\"muted\\">React or BFF</text>\\n\\n        <rect x=\\"516\\" y=\\"28\\" width=\\"210\\" height=\\"112\\" rx=\\"14\\" class=\\"box2\\"></rect>\\n        <text x=\\"621\\" y=\\"68\\" text-anchor=\\"middle\\" class=\\"title\\">Identity provider</text>\\n        <text x=\\"621\\" y=\\"96\\" text-anchor=\\"middle\\" class=\\"muted\\">login + consent</text>\\n\\n        <rect x=\\"786\\" y=\\"118\\" width=\\"170\\" height=\\"112\\" rx=\\"14\\" class=\\"box\\"></rect>\\n        <text x=\\"871\\" y=\\"158\\" text-anchor=\\"middle\\" class=\\"title\\">Resource API</text>\\n        <text x=\\"871\\" y=\\"186\\" text-anchor=\\"middle\\" class=\\"muted\\">FastAPI</text>\\n\\n        <line x1=\\"194\\" y1=\\"128\\" x2=\\"260\\" y2=\\"128\\" class=\\"accent\\" stroke-width=\\"2\\" marker-end=\\"url(#identity-arrow)\\"></line>\\n        <path d=\\"M450 100 C480 60 490 60 516 78\\" class=\\"accent2\\" stroke-width=\\"2\\" marker-end=\\"url(#identity-arrow-purple)\\"></path>\\n        <path d=\\"M726 94 C770 104 790 122 810 142\\" class=\\"accent\\" stroke-width=\\"2\\" marker-end=\\"url(#identity-arrow)\\"></path>\\n        <text x=\\"482\\" y=\\"48\\" text-anchor=\\"middle\\" class=\\"muted\\">OIDC request</text>\\n        <text x=\\"768\\" y=\\"82\\" text-anchor=\\"middle\\" class=\\"muted\\">access token</text>\\n      </svg>\\n      <p class=\\"muted\\">The IdP authenticates the user. The API still makes its\\n      own authorization decision for each request.</p>\\n    </div>\\n\\n    <h2 id=\\"2-sso-is-an-outcome-not-a-token-format\\">2) SSO is an outcome, not a token format</h2>\\n\\n    <p><strong>Single sign-on</strong> means the user can move between trusted\\n    applications without repeatedly entering credentials. It is an experience\\n    created by a shared IdP session and federation protocols. SSO is not itself\\n    an API protocol and does not tell your FastAPI endpoint which records the\\n    caller may access.</p>\\n\\n    <p>When the user signs in to App A, the IdP may create its own secure\\n    browser session. Later, App B redirects the same browser to the IdP. The\\n    IdP recognizes its session, may skip the credential prompt, and completes a\\n    new authorization flow for App B. Each application still receives tokens\\n    intended for that application; one universal token should not be replayed\\n    everywhere.</p>\\n\\n    <h2 id=\\"3-oauth-2-0-delegates-access-to-an-api\\">3) OAuth 2.0 delegates access to an API</h2>\\n\\n    <p>OAuth separates four roles. Keeping these roles distinct prevents most\\n    terminology mistakes:</p>\\n\\n    <table>\\n      <thead>\\n        <tr><th>OAuth role</th><th>In this book\'s example</th><th>Responsibility</th></tr>\\n      </thead>\\n      <tbody>\\n        <tr><td>Resource owner</td><td>The signed-in user</td><td>Owns or is authorized to act on protected data.</td></tr>\\n        <tr><td>Client</td><td>React app or backend-for-frontend</td><td>Requests delegated access; it is not the API being protected.</td></tr>\\n        <tr><td>Authorization server</td><td>The IdP</td><td>Authenticates, obtains consent/policy approval, and issues tokens.</td></tr>\\n        <tr><td>Resource server</td><td>FastAPI</td><td>Validates an access token and authorizes the requested operation.</td></tr>\\n      </tbody>\\n    </table>\\n\\n    <p>The client asks for scopes such as <code>documents:read</code>. The\\n    authorization server may issue an <strong>access token</strong>. The client\\n    sends that token to the API using\\n    <code>Authorization: Bearer &lt;access-token&gt;</code>. The API validates\\n    the token\'s signature or introspection result, issuer, audience, expiry,\\n    and relevant authorization claims before serving data.</p>\\n\\n    <div class=\\"tr-warn\\">\\n      <strong>OAuth alone is not a login protocol.</strong>\\n      An access token is addressed to a resource server and represents delegated\\n      API access. Treating arbitrary access-token contents as a portable user\\n      profile couples the client to one provider and can create token-substitution\\n      vulnerabilities.\\n    </div>\\n\\n    <h2 id=\\"4-oidc-adds-a-standard-authentication-result\\">4) OIDC adds a standard authentication result</h2>\\n\\n    <p>OpenID Connect is an identity layer on top of OAuth 2.0. The client\\n    requests the <code>openid</code> scope. After the user authenticates, the\\n    client receives an <strong>ID token</strong> intended for the client. The ID\\n    token says who authenticated, which issuer authenticated them, which client\\n    it was issued to, and when that authentication result expires.</p>\\n\\n    <pre><code class=\\"language-json\\">{\\n  \\"iss\\": \\"https://idp.example.com\\",\\n  \\"sub\\": \\"00u123stable-subject\\",\\n  \\"aud\\": \\"web-client-id\\",\\n  \\"exp\\": 1785400000,\\n  \\"iat\\": 1785396400,\\n  \\"nonce\\": \\"request-bound-random-value\\",\\n  \\"email\\": \\"alice@example.com\\"\\n}</code></pre>\\n\\n    <p>The durable external identity key is normally the pair\\n    <code>(iss, sub)</code>. Email addresses can change, be recycled, or be\\n    absent. Store the issuer and subject when mapping the external identity to\\n    your internal <code>user_id</code>.</p>\\n\\n    <h2 id=\\"5-keep-id-tokens-access-tokens-refresh-tokens-and-sessions-separate\\">5) Keep ID tokens, access tokens, refresh tokens, and sessions separate</h2>\\n\\n    <table>\\n      <thead>\\n        <tr><th>Credential</th><th>Intended recipient</th><th>Primary purpose</th><th>Where it should go</th></tr>\\n      </thead>\\n      <tbody>\\n        <tr><td>ID token</td><td>The client</td><td>Authentication result and identity claims.</td><td>Client sign-in processing; not as the general API credential.</td></tr>\\n        <tr><td>Access token</td><td>The API named by its audience/resource</td><td>Authorize API calls within scopes and policy.</td><td><code>Authorization: Bearer ...</code> to that resource server.</td></tr>\\n        <tr><td>Refresh token</td><td>The authorized client</td><td>Obtain new access tokens without another full sign-in.</td><td>Prefer a confidential backend or other protected storage; rotate and revoke.</td></tr>\\n        <tr><td>Application session cookie</td><td>Your web application/BFF</td><td>Maintain the app\'s local browser session.</td><td><code>Secure</code>, <code>HttpOnly</code>, appropriately scoped cookie.</td></tr>\\n      </tbody>\\n    </table>\\n\\n    <p>A backend-for-frontend (BFF) can keep OAuth tokens server-side and give\\n    the browser only a hardened session cookie. A pure SPA can use Authorization\\n    Code with PKCE, but must account for browser token-theft risk and should\\n    avoid persistent storage when the architecture allows it.</p>\\n\\n    <h2 id=\\"6-why-authorization-code-with-pkce-is-the-default-teaching-flow\\">6) Why Authorization Code with PKCE is the default teaching flow</h2>\\n\\n    <p>The browser does not receive tokens directly from the authorization\\n    endpoint. It receives a short-lived, single-use authorization\\n    <strong>code</strong>. The client then exchanges that code at the token\\n    endpoint. PKCE binds the code to a secret value created for that particular\\n    authorization attempt:</p>\\n\\n    <ol>\\n      <li>The client generates a random <code>code_verifier</code>.</li>\\n      <li>It sends a derived <code>code_challenge</code> with the authorization request.</li>\\n      <li>The IdP authenticates the user and redirects back with a code.</li>\\n      <li>The client sends the original verifier when exchanging the code.</li>\\n      <li>The authorization server checks that the verifier matches the earlier challenge before issuing tokens.</li>\\n    </ol>\\n\\n    <p>PKCE limits the usefulness of a stolen authorization code. It does not\\n    replace redirect-URI validation, <code>state</code> for request correlation\\n    and CSRF defense, OIDC <code>nonce</code> validation, TLS, or secure token\\n    storage.</p>\\n\\n    <h2 id=\\"7-authentication-is-not-application-authorization\\">7) Authentication is not application authorization</h2>\\n\\n    <p>After token validation, your application still decides what the caller\\n    may do. A valid login does not automatically grant access to every tenant,\\n    document, or administrative operation.</p>\\n\\n    <div class=\\"analogy-box\\">\\n      <p>Imagine a company building with a receptionist.</p>\\n      <ul>\\n        <li><strong>OAuth 2.0</strong> is a visitor pass that grants access to specific rooms: it is delegated authorization.</li>\\n        <li><strong>OIDC</strong> adds a verified identity badge: the client can establish who signed in.</li>\\n        <li><strong>Your application policy</strong> is the door controller for each room: it checks tenant membership, role, ownership, and operation.</li>\\n      </ul>\\n    </div>\\n\\n    <p>Scopes express what an access token permits at an API boundary. Roles and\\n    groups are organizational inputs. Tenant membership and resource ownership\\n    are application data. Your authorization layer may combine all of them, but\\n    they are not interchangeable.</p>\\n\\n    <h2 id=\\"8-common-mistakes-and-the-correct-mental-model\\">8) Common mistakes and the correct mental model</h2>\\n\\n    <table>\\n      <thead><tr><th>Mistake</th><th>Correction</th></tr></thead>\\n      <tbody>\\n        <tr><td>\u201cOAuth logs the user in.\u201d</td><td>OAuth delegates API access; OIDC standardizes authentication on top of it.</td></tr>\\n        <tr><td>\u201cSSO means one token works for every app.\u201d</td><td>SSO normally reuses the IdP session while issuing audience-specific results to each client/resource.</td></tr>\\n        <tr><td>\u201cThe API should accept the ID token.\u201d</td><td>The API normally accepts an access token whose audience/resource identifies that API.</td></tr>\\n        <tr><td>\u201cEmail is the user ID.\u201d</td><td>Use the issuer and subject as the external stable key; treat email as a mutable attribute.</td></tr>\\n        <tr><td>\u201cA valid token means the request is authorized.\u201d</td><td>Token validation authenticates the credential; application policy still authorizes the operation and resource.</td></tr>\\n        <tr><td>\u201cJWT validation means decoding the payload.\u201d</td><td>Decoding is not trust. Verify signature, issuer, audience, expiry, and required claims.</td></tr>\\n      </tbody>\\n    </table>\\n\\n    <h2 id=\\"9-the-flow-you-will-implement-next\\">9) The flow you will implement next</h2>\\n\\n    <pre><code class=\\"language-text\\">Browser          Client app          Identity provider          FastAPI\\n   |                  |                       |                     |\\n   | click sign in    |                       |                     |\\n   |-----------------&gt;| authorize + PKCE      |                     |\\n   |                  |----------------------&gt;|                     |\\n   |          authenticate / consent          |                     |\\n   |&lt;----------------------------------------&gt;|                     |\\n   |                  | code + state          |                     |\\n   |                  |&lt;----------------------|                     |\\n   |                  | code + verifier       |                     |\\n   |                  |----------------------&gt;|                     |\\n   |                  | ID token + access token                     |\\n   |                  |&lt;----------------------|                     |\\n   |                  |        Authorization: Bearer access_token   |\\n   |                  |--------------------------------------------&gt;|\\n   |                  |        validate token + authorize resource  |</code></pre>\\n\\n    <div class=\\"tr-tip\\">\\n      <strong>Standards note</strong>\\n      OAuth 2.1 is a consolidation of modern OAuth practice, but it remains an\\n      Internet-Draft rather than a replacement RFC at the time of this edition.\\n      Production designs should follow the OAuth 2.0 Security Best Current\\n      Practice, use Authorization Code with PKCE, and avoid the implicit and\\n      resource-owner-password grants.\\n    </div>\\n\\n    <p class=\\"footer-note\\">Continue to\\n    <a href=\\"/tutorials/part2-backend-platform-security/07-oidc-oauth2-pkce-fastapi\\">OIDC + OAuth2 + PKCE in\\n    FastAPI</a>, where this vocabulary becomes a concrete message sequence,\\n    token-validation dependency, and stable user/tenant mapping.</p>"}'),d={title:"SSO, OAuth 2.0, and OpenID Connect: The Identity Primer",slug:"/part2-backend-platform-security/06-sso-oauth2-oidc-primer",description:"Authentication terminology feels confusing because several layers happen during one click on \u201cSign in.\u201d This chapter separates the user experience, delegation protocol, identity protocol, browser session, and API auth...",sidebar_label:"7. SSO, OAuth 2.0, and OIDC primer",pagination_label:"7. SSO, OAuth 2.0, and OIDC primer",hide_title:!0,hide_table_of_contents:!0},c=void 0,l={},h=[];function p(e){return(0,i.jsx)(s.A,{content:r})}function u(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(p,{...e})}):p()}}}]);